import {hardwarePresetBank,applyHardwarePreset,mountHardwareMasterPresets} from './hardware-presets.js';
export const isExoStrip=id=>id==='exostrip';
export const EXO_STRIP_BANKS=Object.freeze([['01 / EQUALIZER',['highpass','body','presence','air']],['02 / DYNAMICS',['threshold','ratio','attack','release']],['03 / OUTPUT',['mix','output']]]);
export function exoStripPresetBank(id,definition,factory,storage){return isExoStrip(id)?hardwarePresetBank(id,definition,factory,storage):[];}
export function applyExoStripPreset(state,id,definition,preset){if(!isExoStrip(id))throw Error('Module hors EXO STRIP');return applyHardwarePreset(state,id,definition,preset);}
export function mountExoStripPresets(root,options){return mountHardwareMasterPresets(root,{...options,faceSelector:'.exo-strip-hardware',collection:'EXO',sectionClass:'exo-strip-presets',saveAttribute:'data-exo-strip-save'});}
const active=new WeakMap(),hz=Float32Array.from({length:241},(_,i)=>20*1000**(i/240)),x=f=>28+Math.log(f/20)/Math.log(1000)*304,y=db=>80-Math.max(-24,Math.min(24,db))*2.4;
let context;
export function createStripAnalysis(ctx){return ['highpass','lowshelf','peaking','highshelf'].map((type,i)=>{const n=ctx.createBiquadFilter();n.type=type;if(i===1)n.frequency.value=180;if(i===2){n.frequency.value=3200;n.Q.value=.7;}if(i===3)n.frequency.value=10000;return n;});}
export function stripEqResponse(filters,s,frequencies){filters[0].frequency.value=s.highpass;filters[1].gain.value=s.body;filters[2].gain.value=s.presence;filters[3].gain.value=s.air;const m=new Float32Array(frequencies.length),p=new Float32Array(frequencies.length),db=new Float64Array(frequencies.length);for(const n of filters){n.getFrequencyResponse(frequencies,m,p);for(let i=0;i<db.length;i++)db[i]+=20*Math.log10(Math.max(1e-9,m[i]));}return db;}
function graph(){return '<svg viewBox="0 0 360 164" role="img" aria-label="Réponse de l’EQ avant compression"><rect x="1" y="1" width="358" height="162" rx="4" fill="#081218" stroke="#31545e"/>'+[20,100,500,1000,5000,10000,20000].map(f=>'<path d="M'+x(f)+' 20V140" stroke="#19343d"/><text x="'+x(f)+'" y="151" text-anchor="middle" fill="#a5c7ce" font-size="8">'+(f>=1000?f/1000+'k':f)+'</text>').join('')+[-24,-12,0,12,24].map(v=>'<path d="M28 '+y(v)+'H332" stroke="'+(v===0?'#527a85':'#19343d')+'"/><text x="24" y="'+(y(v)+3)+'" text-anchor="end" fill="#a5c7ce" font-size="8">'+v+'</text>').join('')+'<path data-strip-eq fill="none" stroke="#6ef2eb" stroke-width="2.3"/></svg>';}
export function mountExoStrip(root,{state,getStage,master=false}){
 const params=root.querySelector(master?'.master-module-params':'.plugin-window-params');if(!params||root.querySelector('.exo-strip-hardware'))return;
 const nodes=[...params.querySelectorAll('.param')],byKey=new Map(nodes.map(n=>{const i=n.querySelector('input');return [(i?.dataset.param||i?.dataset.masterParam||'').split('.').at(-1),n];}));
 if(nodes.length!==10||EXO_STRIP_BANKS.flatMap(([,ks])=>ks).some(k=>!byKey.has(k)))return;
 const surface=document.createElement('section');surface.className='exo-strip-hardware';surface.setAttribute('aria-label','EXO STRIP Vocal Channel Hardware');
 surface.innerHTML='<header class="exo-strip-brand"><small>WARLIKE / EXO COLLECTION</small><strong>STRIP 04</strong><small>VOCAL CHANNEL · EQ / COMP</small></header><div class="exo-strip-display">'+graph()+'<div class="exo-strip-readouts"><output data-strip-hp></output><span>EQ · PRE COMP · 48 kHz</span></div><section class="exo-strip-gr"><header><small>COMPRESSOR GAIN REDUCTION</small><output data-strip-gr>—</output></header><div class="exo-strip-leds">'+Array.from({length:24},(_,i)=>'<i data-strip-led="'+i+'"></i>').join('')+'</div><div class="exo-strip-readouts"><span>0</span><span>6</span><span>12</span><span>18</span><span>24 dB</span></div><output data-strip-status></output></section><div class="exo-strip-readouts"><output data-strip-mix></output><output data-strip-output></output></div><small>Réponse calculée des filtres avant compresseur. Réduction native du compresseur avant Mix ; le chemin direct est retardé de 6 ms pour alignement.</small></div><footer>4 FILTERS · 9 dB KNEE · 6 ms DRY ALIGNMENT · NATIVE DSP</footer>';
 params.before(surface);surface.querySelector('footer').before(params);params.classList.add('exo-strip-controls');
 const groups=EXO_STRIP_BANKS.map(([label,ks],i)=>{const bank=document.createElement('section');bank.className='exo-strip-bank';bank.style.setProperty('--vox-bank',['#60c9d8','#6ef2eb','#e6c38d'][i]);const h=document.createElement('h4');h.textContent=label;bank.append(h,...ks.map(k=>byKey.get(k)));return bank;});params.replaceChildren(...groups);
 context??=new OfflineAudioContext(1,128,48000);active.set(surface,{state,getStage,filters:createStripAnalysis(context),signature:''});paint(surface);return surface;
}
function paint(face){const e=active.get(face),s=e?.state();if(!s)return;const signature=[s.highpass,s.body,s.presence,s.air].join(':');if(signature!==e.signature){e.signature=signature;const db=stripEqResponse(e.filters,s,hz);face.querySelector('[data-strip-eq]').setAttribute('d',Array.from(hz,(f,i)=>(i?'L':'M')+x(f).toFixed(2)+' '+y(db[i]).toFixed(2)).join(''));face.querySelector('[data-strip-hp]').textContent='LOW CUT '+Math.round(s.highpass)+' Hz';}
 const enabled=s.enabled!==false,comp=enabled?e.getStage?.()?.comp:null,gr=comp&&Number.isFinite(comp.reduction)?Math.min(0,comp.reduction):0;
 face.querySelector('[data-strip-gr]').textContent=enabled&&!comp?'—':gr.toFixed(1)+' dB';for(const led of face.querySelectorAll('[data-strip-led]'))led.classList.toggle('lit',Number(led.dataset.stripLed)<Math.round(-gr));
 face.querySelector('[data-strip-status]').textContent=!enabled?'BYPASS':s.mix===0?'DRY':!comp?'HORS SIGNAL':gr<-.1?'COMPRESSING':'ACTIVE';
 const mix=enabled?s.mix:0;face.querySelector('[data-strip-mix]').textContent='DRY '+Math.round((1-mix)*100)+'% / WET '+Math.round(mix*100)+'%';face.querySelector('[data-strip-output]').textContent='OUTPUT '+(enabled?s.output:0).toFixed(1)+' dB';
}
export function updateExoStripFaces(root=document){root.querySelectorAll('.exo-strip-hardware').forEach(paint);}
